package com.wandertrace.service;
import com.wandertrace.dto.ContentDtos.*;import com.wandertrace.exception.NotFoundException;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DestinationService {private final JdbcTemplate db;private final TripAccessService access;private final ContentAccessService content;public DestinationService(JdbcTemplate db,TripAccessService access,ContentAccessService content){this.db=db;this.access=access;this.content=content;}public List<Destination> list(UUID user,UUID trip){access.requireView(user,trip);return db.queryForList("select * from destinations where trip_id=? order by created_at",trip).stream().map(this::map).toList();}@Transactional public Destination create(UUID user,UUID trip,DestinationRequest r){access.requireEdit(user,trip);UUID id=UUID.randomUUID();db.update("insert into destinations(id,trip_id,name,city,country,latitude,longitude,description,cover_image_url)values(?,?,?,?,?,?,?,?,?)",id,trip,r.name(),r.city(),r.country(),r.latitude(),r.longitude(),r.description(),r.coverImageUrl());return get(user,id); }public Destination get(UUID user,UUID id){access.requireView(user,content.tripForDestination(id));return map(one(id));}@Transactional public Destination update(UUID user,UUID id,DestinationRequest r){access.requireEdit(user,content.tripForDestination(id));db.update("update destinations set name=?,city=?,country=?,latitude=?,longitude=?,description=?,cover_image_url=?,updated_at=now() where id=?",r.name(),r.city(),r.country(),r.latitude(),r.longitude(),r.description(),r.coverImageUrl(),id);return get(user,id);}@Transactional public void delete(UUID user,UUID id){access.requireEdit(user,content.tripForDestination(id));db.update("delete from destinations where id=?",id);}private Map<String,Object> one(UUID id){var r=db.queryForList("select * from destinations where id=?",id);if(r.isEmpty())throw new NotFoundException("Destination not found");return r.getFirst();}private Destination map(Map<String,Object> r){return new Destination((UUID)r.get("id"),(UUID)r.get("trip_id"),(String)r.get("name"),(String)r.get("city"),(String)r.get("country"),number(r.get("latitude")),number(r.get("longitude")),(String)r.get("description"),(String)r.get("cover_image_url"),instant(r.get("created_at")),instant(r.get("updated_at")));}private Double number(Object x){return x==null?null:((Number)x).doubleValue();}private Instant instant(Object x){return ((java.sql.Timestamp)x).toInstant();}}
